function(container, apiUrl, tables) {
  let currentOrders = [];
  let stores = [];
  let products = [];
  let suppliers = [];

  // 初期データの取得
  async function loadInitialData() {
    try {
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ
      products = await window.aivicApi.list(2) || []; // 商品マスタ
      suppliers = await window.aivicApi.list(2) || []; // 仕入先（商品マスタから取得）

      renderStoreOptions();
    } catch (error) {
      showError('初期データの読み込みに失敗しました');
    }
  }

  // 店舗選択肢の描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 発注データの描画
  function renderOrders(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      updateSummary();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      const statusBadge = getStatusBadge(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.発注ID}">
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" ${isDisabled}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${getSupplierName(product.仕入先ID)}</td>
          <td style="text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateSummary();
  }

  // 仕入先名の取得
  function getSupplierName(supplierId) {
    const supplier = suppliers.find(s => s.仕入先ID === supplierId);
    return supplier ? supplier.仕入先名 : '未設定';
  }

  // ステータスバッジの生成
  function getStatusBadge(status) {
    const statusConfig = {
      '送信待ち': { color: '#ffa500', bg: 'rgba(255, 165, 0, 0.1)' },
      '送信済み': { color: '#00c851', bg: 'rgba(0, 200, 81, 0.1)' },
      '送信失敗': { color: '#ff6a00', bg: 'rgba(255, 106, 0, 0.1)' },
      'キャンセル': { color: '#6c757d', bg: 'rgba(108, 117, 125, 0.1)' }
    };

    const config = statusConfig[status] || statusConfig['送信待ち'];
    return `<span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${config.bg}; color: ${config.color};">${status || '送信待ち'}</span>`;
  }

  // サマリー情報の更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');
    const selectedCount = checkboxes.length;

    let totalAmount = 0;
    checkboxes.forEach(cb => {
      const order = currentOrders.find(o => o.発注ID === cb.dataset.id);
      if (order) {
        totalAmount += order.発注金額 || 0;
      }
    });

    container.querySelector('#selected-count').textContent = `選択件数: ${selectedCount}件`;
    container.querySelector('#total-amount').textContent = `合計金額: ¥${totalAmount.toLocaleString()}`;
    container.querySelector('#btn-send').disabled = selectedCount === 0;
  }

  // 店舗別発注データの読み込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrders([]);
      return;
    }

    try {
      const orders = await window.aivicApi.list(7) || []; // 発注データ
      currentOrders = orders.filter(order => 
        order.店舗ID === storeId && 
        order.発注日 && 
        new Date(order.発注日).toDateString() === new Date().toDateString()
      );

      renderOrders(currentOrders);
    } catch (error) {
      showError('発注データの読み込みに失敗しました');
    }
  }

  // 発注送信処理
  async function sendOrders() {
    const selectedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');

    if (selectedCheckboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    const selectedIds = Array.from(selectedCheckboxes).map(cb => cb.dataset.id);
    const selectedOrders = currentOrders.filter(order => selectedIds.includes(order.発注ID));

    // 送信済みデータのチェック
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');
    if (alreadySent.length > 0) {
      showError('この発注データは既に送信済みです。重複送信はできません。');
      return;
    }

    // 発注数量0のチェック
    const zeroQuantity = selectedOrders.filter(order => (order.発注数量 || 0) === 0);
    if (zeroQuantity.length > 0) {
      const proceed = confirm(`発注数量が0の商品が${zeroQuantity.length}件含まれています。これらを除外して送信しますか？`);
      if (!proceed) return;

      // 発注数量0の商品を除外
      const validOrders = selectedOrders.filter(order => (order.発注数量 || 0) > 0);
      if (validOrders.length === 0) {
        showError('送信可能な発注データがありません');
        return;
      }
    }

    showSendDialog(selectedOrders);
  }

  // 送信確認ダイアログの表示
  function showSendDialog(orders) {
    const dialog = container.querySelector('#send-dialog');
    const message = container.querySelector('#send-confirm-message');

    const totalAmount = orders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    message.innerHTML = `
      <p>以下の発注データを送信しますか？</p>
      <ul style="margin: 10px 0; padding-left: 20px;">
        <li>選択件数: ${orders.length}件</li>
        <li>合計金額: ¥${totalAmount.toLocaleString()}</li>
      </ul>
    `;

    dialog.classList.remove('hidden');

    // 確認ボタンのイベント
    const confirmBtn = container.querySelector('#btn-confirm');
    const cancelBtn = container.querySelector('#btn-cancel');

    const handleConfirm = async () => {
      dialog.classList.add('hidden');
      await executeSend(orders);
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    const handleCancel = () => {
      dialog.classList.add('hidden');
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    confirmBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // 実際の送信処理
  async function executeSend(orders) {
    try {
      let successCount = 0;
      let failCount = 0;

      for (const order of orders) {
        try {
          await window.aivicApi.update(7, order.発注ID, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user-id'
          });
          successCount++;
        } catch (error) {
          failCount++;
        }
      }

      if (successCount > 0) {
        showSuccess(`${successCount}件の発注を正常に送信しました`);
      }

      if (failCount > 0) {
        showError(`${failCount}件の発注送信に失敗しました`);
      }

      // データを再読み込み
      const storeId = container.querySelector('#store-select').value;
      await loadOrdersByStore(storeId);

    } catch (error) {
      showError('発注送信処理中にエラーが発生しました');
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
    const csvData = [headers];

    currentOrders.forEach(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      csvData.push([
        product.商品コード || '',
        product.商品名 || '',
        order.予測数量 || 0,
        order.発注数量 || 0,
        getSupplierName(product.仕入先ID),
        order.発注金額 || 0,
        order.発注ステータス || '送信待ち'
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    successDiv.classList.add('hidden');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');

    errorDiv.classList.add('hidden');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');

    setTimeout(() => {
      successDiv.classList.add('hidden');
    }, 5000);
  }

  // イベントリスナーの設定
  container.querySelector('#store-select').addEventListener('change', (e) => {
    loadOrdersByStore(e.target.value);
  });

  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
    });
    updateSummary();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      updateSummary();

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not([disabled])');
      const selectAllCheckbox = container.querySelector('#select-all');

      selectAllCheckbox.checked = allCheckboxes.length > 0 && allCheckboxes.length === checkedCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < allCheckboxes.length;
    }
  });

  container.querySelector('#btn-send').addEventListener('click', sendOrders);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 初期データの読み込み
  loadInitialData();
}
